INSERT INTO `produtos` (`id`, `codigo`, `codigo_cq`, `nome`, `descricao`, `anotacoes`, `local_uso`, `ativo`, `created_at`, `updated_at`, `preco`, `categoria`, `preco_custo`, `estoque_minimo`, `unidade`, `tiny_id`, `modo_uso`, `tiny_sync_at`, `anotacoes_internas`) VALUES (488, 'DUO-MASK', NULL, 'Creme Duo Mask', 'Ácido glicólico 4,0%\\nÁcido salicílico 4,0%\\nMelavan qs\\nBionaissance Sensitive qs\\nB. Aquelane pura qsp 100g pH4,0', '', NULL, 1, '2026-03-11 08:29:31', '2026-03-26 10:12:51', 220, NULL, 0, NULL, 'un', 889820503, '1. Uso como Máscara: Aplique camada generosa e uniforme em toda a face, 1 vez ou mais por semana.\\nDeixe agir por 15 min e enxágue bem. Evite pálpebras, contorno dos olhos e o vermelho dos lábios.\\n2. Uso para Limpeza: espalhe na face 2x ao dia e enxágue em seguida com água abundante.', '2026-03-16 07:49:41', 'Numa versão colocada cor amarelo naturele 23gt para ficar alaranjado...\\r\\nVou te passar essas anotações, pra não esquecer de te falar, porque registrei assim no sistema:  \\r\\n\\r\\nA Duo-Mask, se tem glicólico 4% e Salicilico 4%, se chama Duo-Mask 44 ou Duo-Máscara 44. Assim a gente não precisa decorar a composição. \\r\\n\\r\\nO que você já existe e mandamos para o Vasanth tem glic. 3% e salic. 2%, então se chama Duo-Mask 32.\\r\\n\\r\\nSempre o primeiro número é do glicólico e o segundo número é do salicílico.\\r\\n\\r\\nE podem ser usados como máscara (deixa 20 min, tira e não põe o creme da noite)\\r\\nou como creme de Limpeza, 2, 3x/dia principalmente para quem tem acne, para o que é  melhor o nº 44. Aplicar massageando e logo enxaguar com água.');
INSERT INTO `produtos` (`id`, `codigo`, `codigo_cq`, `nome`, `descricao`, `anotacoes`, `local_uso`, `ativo`, `created_at`, `updated_at`, `preco`, `categoria`, `preco_custo`, `estoque_minimo`, `unidade`, `tiny_id`, `modo_uso`, `tiny_sync_at`, `anotacoes_internas`) VALUES (489, 'ESTRIAS-CREME', NULL, 'Creme de Estrias', 'Alfahidroxiácido glicólico 8,0%\\nNeodeline 6,0%\\nB. Hydravelt Soft com pH 3,5 qsp 100g', '', NULL, 1, '2026-03-11 08:29:31', '2026-03-26 10:12:50', 188, NULL, 0, NULL, 'un', 889820507, 'Aplique nas áreas com estrias, 2 vezes ao dia. A seguir, aplique\\no Creme do Corpo por cima, que também pode ser utilizado em todo o corpo.', '2026-03-16 07:49:41', 'antes de nov/21 era \"gel\":\\r\\nGel para estrias\\r\\n\\r\\nAlfahidroxiácido glicólico 8,0%\\r\\nNeodeline 6,0%\\r\\nB. Hydravelt com pH 3,5 qsp100g\\r\\nAplicar nas áreas com estrias, 2 vez ao dia. A seguir, aplique \\r\\no Creme do Corpo por cima, e em todo o corpo');
INSERT INTO `produtos` (`id`, `codigo`, `codigo_cq`, `nome`, `descricao`, `anotacoes`, `local_uso`, `ativo`, `created_at`, `updated_at`, `preco`, `categoria`, `preco_custo`, `estoque_minimo`, `unidade`, `tiny_id`, `modo_uso`, `tiny_sync_at`, `anotacoes_internas`) VALUES (490, 'FOLICULITE-GLIC-8-30G', NULL, 'Creme com Glicólico para Foliculite e Acne Corporal', 'Alfahidroxiácido glicólico 8,0%\\nNeodeline 6,0%\\nB. Hydravelt Soft com pH 3,5 qsp ... 30g', '', NULL, 1, '2026-03-11 08:29:31', '2026-03-26 10:12:51', 196, NULL, 0, NULL, 'un', 958252927, 'Uso: Aplique duas vezes ao dia, pela manhã e à noite.\\nUse apenas nas áreas indicadas, em pequena quantidade.\\nNão há necessidade de alternar o uso no início.\\nDurante o dia, proteja a área em tratamento do sol.\\nSe ocorrer vermelhidão, interrompa o uso e contate-nos.', '2026-03-16 07:49:41', '\"FOLICULITE\"= forma inflamatória da QUERATOSE PILAR\\r\\ndra LA passou para Rafael Heredia jan 23');
