INSERT INTO `produtos` (`id`, `codigo`, `codigo_cq`, `nome`, `descricao`, `anotacoes`, `local_uso`, `ativo`, `created_at`, `updated_at`, `preco`, `categoria`, `preco_custo`, `estoque_minimo`, `unidade`, `tiny_id`, `modo_uso`, `tiny_sync_at`, `anotacoes_internas`) VALUES (848, 'REVELUMIE-G30', NULL, 'Sérum de Vitamina C Rejuvenescedor e Firmador', 'B. Neolipossome VC 6,0%\\nB. Lumine C Nano qs\\nB. Vitessence Revelumiê qsp 30g\\nApós lavar a pele, aplique-o no horário recomendado.\\nAguarde  30 segundos, e a seguir aplique os outros cremes.', '', NULL, 1, '2026-03-11 08:29:33', '2026-03-26 10:12:50', 263, NULL, 0, NULL, 'un', 904837088, '', '2026-03-16 07:49:43', '\"LUMI feito por LF com lumineCense 2%\": na etq vai a base \"Vitessence Plus\" (sem \"VC\")\\r\\n\\r\\nFÓRMULA ANTIGA qdo usava \"B. Lumine-C-Nano como qsp, antesde 15/8/19:\\r\\n\\r\\nB. Vitessence VC Plus 15%\\r\\nNeolipossome VC 6,0%\\r\\nSérum Lumine C Nano qsp 30g\\r\\nApós lavar a pele, aplique-o no horário recomendado.\\r\\nAguarde 15 segundos, e a seguir aplique os outros cremes.');
INSERT INTO `produtos` (`id`, `codigo`, `codigo_cq`, `nome`, `descricao`, `anotacoes`, `local_uso`, `ativo`, `created_at`, `updated_at`, `preco`, `categoria`, `preco_custo`, `estoque_minimo`, `unidade`, `tiny_id`, `modo_uso`, `tiny_sync_at`, `anotacoes_internas`) VALUES (849, 'SUICO-G100', NULL, 'Creme Suiço Ultra Hidratante', 'Innovare 6,0%\\nB. Hydraction Suisse qsp 100g', '', NULL, 1, '2026-03-11 08:29:33', '2026-03-24 08:55:38', 190, NULL, 0, NULL, 'un', 889822297, 'Aplicar 1 a 3 x/dia nas áreas ressecadas de face, pescoço e colo, ou outras áreas que forem recomendadas.\\nÀ noite, utilize-o sobre o Creme da Noite. Pela manhã, use-o por baixo do Creme do Dia.\\nTambém pode ser usado de forma isolada como potente hidratante.', '2026-03-16 07:49:43', '');
