INSERT INTO `produtos` (`id`, `codigo`, `codigo_cq`, `nome`, `descricao`, `anotacoes`, `local_uso`, `ativo`, `created_at`, `updated_at`, `preco`, `categoria`, `preco_custo`, `estoque_minimo`, `unidade`, `tiny_id`, `modo_uso`, `tiny_sync_at`, `anotacoes_internas`) VALUES (867, 'W-HYALU-GEL-HYDRAVELT', NULL, 'Creme Dos Olhos Innovare Gel', 'Innovare 6,0%\\nB. Eyecontour Hyalu qs\\nÁgua purificada 20,0%\\nB. Hydravelt Soft qsp 15g', '', NULL, 1, '2026-03-11 08:29:33', '2026-03-26 10:12:51', 153, NULL, 0, NULL, 'un', 933074640, 'Usar sobre os cremes do Dia e da Noite.\\nAplicar nas pálpebras inferiores, na lateral dos olhos,\\nao redor dos lábios e entre as sobrancelhas', '2026-03-16 07:49:43', 'só pac. Carla Cruz Murta de Castro - porque???');
INSERT INTO `produtos` (`id`, `codigo`, `codigo_cq`, `nome`, `descricao`, `anotacoes`, `local_uso`, `ativo`, `created_at`, `updated_at`, `preco`, `categoria`, `preco_custo`, `estoque_minimo`, `unidade`, `tiny_id`, `modo_uso`, `tiny_sync_at`, `anotacoes_internas`) VALUES (868, 'W-TONALITE-1-MEZZOTONO-A-G30', NULL, 'Creme Dia BB Cream Tonalité 1 Mezzotono A', 'FPS60 anti-UVA/B\\nNutradvance 6,0%\\nConcentrée Red Plus 1,5%\\nB. Tonalité 1 qsp 30g', '', NULL, 1, '2026-03-11 08:29:33', '2026-03-26 10:12:51', 178, NULL, 0, NULL, 'un', 940732028, 'Aplique uma a duas vezes ao dia.', '2026-03-16 07:49:43', 'PEDIR PARA LF PREPARAR O CONCENTRADO - ver Arq técn \"modo de preparo dos cremes...\"\\r\\nAmostra nº 1 extra-suave  08/09/25 que a pac. Karine Giacomeli Moraes de Lima e Dra LA gostaram 25/9/25\\r\\nPREPARO DO TONALITÉ-1 Red Plus Mezzotono A:\\r\\nPasta Concentrée Red Plus (pigm verm CI 77491 a 4,55% em qsp TON1)\\r\\nIngredientes para qsp 100g:\\r\\nPasta RED 1,5g\\r\\nTonalité 1 98,5g   - qsp 100g\\r\\nColocar 98,5g de Tonalité 1 no saquinho\\r\\nAdicionar 1,5g de pasta RED (i.e. 0,07g pigm red) \\r\\nHomogeneizar sem aerar.');
